import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { chiSquareUpper, correlationTest, fisherExact, formatP, fUpper, holm, kruskalWallis, mannWhitney, meanInterval, normalUpper, oneWayAnova, tCritical, tTwoSided, welchAnova, welchT, wilsonInterval } from '../lib/inference.ts';
import { averageRanks, pairedCorrelation } from '../lib/analysis-recipes.ts';

// Values generated by tools/build-inference-reference.py with SciPy and statsmodels.
const ref = JSON.parse(readFileSync(new URL('./fixtures/inference-reference.json', import.meta.url), 'utf8'));
function close(actual, expected, label, relative = 1e-9) {
  assert.ok(Number.isFinite(actual), `${label}: ${actual}`);
  const tolerance = Math.max(1e-13, Math.abs(expected) * relative);
  assert.ok(Math.abs(actual - expected) <= tolerance, `${label}: ${actual} vs ${expected}`);
}

test('distribution tails match SciPy, including far tails', () => {
  for (const c of ref.tails.t) close(tTwoSided(c.t, c.df), c.p, `t ${c.t}/${c.df}`);
  for (const c of ref.tails.chi) close(chiSquareUpper(c.x, c.k), c.p, `chi ${c.x}/${c.k}`);
  for (const c of ref.tails.f) close(fUpper(c.f, c.d1, c.d2), c.p, `F ${c.f}`);
  for (const c of ref.tails.z) close(normalUpper(c.z), c.p, `z ${c.z}`);
  for (const c of ref.critical) close(tCritical(0.05, c.df), c.q, `t crit ${c.df}`, 1e-10);
});

test('Welch t, its interval and Hedges g agree with SciPy', () => {
  for (const c of ref.welch) {
    const w = welchT(c.x, c.y);
    close(w.t, c.t, 'welch t'); close(w.df, c.df, 'welch df'); close(w.p, c.p, 'welch p');
    close(w.ci.lower, c.lower, 'ci lower'); close(w.ci.upper, c.upper, 'ci upper');
    assert.ok(w.gInterval.lower < w.hedgesG && w.hedgesG < w.gInterval.upper);
  }
  assert.equal(welchT([1], [2, 3]), null);
  assert.equal(welchT([2, 2], [2, 2]), null);
});

test('Mann–Whitney U uses the exact distribution without ties and the corrected normal approximation otherwise', () => {
  for (const c of ref.mannWhitney) {
    const m = mannWhitney(c.x, c.y);
    assert.equal(m.method, c.method);
    close(m.u, c.u, 'U'); close(m.p, c.p, `MWU p (${c.method})`);
  }
});

test('classic ANOVA, Welch ANOVA and Kruskal–Wallis agree with SciPy and statsmodels', () => {
  for (const c of ref.groups) {
    const a = oneWayAnova(c.groups), w = welchAnova(c.groups), k = kruskalWallis(c.groups);
    close(a.f, c.f, 'F'); close(a.p, c.fp, 'F p');
    close(w.f, c.welchF, 'Welch F'); close(w.df2, c.welchDf2, 'Welch df2'); close(w.p, c.welchP, 'Welch p');
    close(k.h, c.h, 'H'); close(k.p, c.hp, 'H p');
    assert.ok(a.etaSquared > 0 && a.etaSquared < 1);
  }
});

test('Pearson and Spearman tests and the Fisher z interval agree with SciPy', () => {
  for (const c of ref.correlation) {
    const r = pairedCorrelation(c.x, c.y), rho = pairedCorrelation(averageRanks(c.x), averageRanks(c.y));
    close(r, c.r, 'r', 1e-12); close(rho, c.rho, 'rho', 1e-12);
    const tr = correlationTest(r, c.x.length, true), ts = correlationTest(rho, c.x.length, false);
    close(tr.p, c.p, 'r p'); close(tr.ci.lower, c.lower, 'r lower'); close(tr.ci.upper, c.upper, 'r upper');
    close(ts.p, c.rhoP, 'rho p'); assert.equal(ts.ci, null);
  }
  assert.equal(correlationTest(0.5, 2, true), null);
  assert.equal(correlationTest(1, 5, true).p, 0);
});

test('chi-square, Fisher exact, Wilson intervals and Holm adjustment agree with references', () => {
  for (const c of ref.chiSquare) {
    const t = c.table, rows = t.map(r => r.reduce((s, v) => s + v, 0)), cols = t[0].map((_, j) => t.reduce((s, r) => s + r[j], 0)), n = rows.reduce((s, v) => s + v, 0);
    let chi = 0; t.forEach((r, i) => r.forEach((o, j) => { const e = rows[i] * cols[j] / n; chi += (o - e) ** 2 / e; }));
    close(chi, c.chi, 'chi'); close(chiSquareUpper(chi, c.df), c.p, 'chi p');
  }
  for (const c of ref.fisher) close(fisherExact(c.table[0][0], c.table[0][1], c.table[1][0], c.table[1][1]), c.p, `fisher ${JSON.stringify(c.table)}`);
  for (const c of ref.wilson) { const w = wilsonInterval(c.k, c.n); close(w.lower, c.lower, 'wilson lower', 1e-12); close(w.upper, c.upper, 'wilson upper', 1e-12); }
  holm(ref.holm.input).forEach((v, i) => close(v, ref.holm.output[i], 'holm'));
});

test('mean interval and APA p formatting', () => {
  const ci = meanInterval([2, 4, 4, 5, 7]);
  close(ci.lower, 4.4 - tCritical(0.05, 4) * Math.sqrt(3.3 / 5), 'mean lower', 1e-12);
  assert.equal(meanInterval([3]), null);
  assert.equal(formatP(0.0004), 'p < .001');
  assert.equal(formatP(0.0456), 'p = .046');
  assert.equal(formatP(null), 'p 不定义');
});
